import {DEFAULT_CONFIG,PRESETS,validateConfig,createChallenge,stepChallenge,exportChallenge,encodeChallenge,decodeChallenge} from './lib/challenge.js';
import {BASE_WEIGHTS,DT} from './lib/learning-core.js';
import {REGIONS} from './lib/model.js';
import {BrainView} from './lib/brain-view.js';

const $=id=>document.getElementById(id),n=(v,d=2)=>Number(v).toFixed(d),copy=v=>structuredClone(v);
let config=copy(DEFAULT_CONFIG),weights=[...BASE_WEIGHTS],provenance={},exp=null,running=false,paused=false,hasStarted=false,checking=false,verification=null,verificationFailure=null;
let generationLabel='Original parameters',runId=0,checkAbort=null,accumulator=0,lastFrame=performance.now(),lastPaint=0,lastEvents=-1,initializing=true,ready=false;
const brain=new BrainView($('brain'));
const rateRows=REGIONS.map(region=>{const row=document.createElement('div');row.className='rate-row';const label=document.createElement('span');label.textContent=region.name;const value=document.createElement('output');const meter=document.createElement('div');meter.className='rate-bar';const bar=document.createElement('i');meter.append(bar);row.append(label,value,meter);$('rate-list').append(row);return {value,bar};});
const presetEntries=Array.isArray(PRESETS)?PRESETS:Object.entries(PRESETS).map(([id,p])=>({id,...p}));
for(const preset of presetEntries){const option=document.createElement('option');option.value=preset.id;option.textContent=preset.label;$('preset').append(option);}const customOption=document.createElement('option');customOption.value='custom';customOption.textContent='Custom challenge';$('preset').append(customOption);
async function json(url,options={}){const res=await fetch(url,{cache:'no-store',...options});const data=await res.json();if(!res.ok)throw Error(data.error||`HTTP ${res.status}`);return data;}
function message(text){$('action-message').textContent=text;}
function selectedPreset(){return presetEntries.find(p=>JSON.stringify(validateConfig(p.config))===JSON.stringify(config));}
function syncControls(){
 $('motion').value=config.motion;$('motion-speed').value=config.speed;$('contrast').value=config.contrast;$('radius').value=config.radius;$('occlusion').checked=config.occlusion.enabled;$('hide-at').value=config.occlusion.at;$('hide-for').value=config.occlusion.duration;
 $('motion-speed-value').textContent=`${n(config.speed)}×`;$('contrast-value').textContent=n(config.contrast);$('radius-value').textContent=n(config.radius,3);$('hide-at-value').textContent=`${n(config.occlusion.at,0)} s`;$('hide-for-value').textContent=`${n(config.occlusion.duration,0)} s`;
 $('motion-speed').disabled=!ready||config.motion!=='sweep';$('hide-at').disabled=!ready||!config.occlusion.enabled;$('hide-for').disabled=!ready||!config.occlusion.enabled;$('occlusion-controls').setAttribute('aria-disabled',String(!config.occlusion.enabled));
 const preset=selectedPreset();$('preset').value=preset?.id||'custom';$('preset-description').textContent=preset?.description||'Your own task. Both controllers face the same conditions.';
}
function newTrial(start=false){
 checkAbort?.abort();runId++;checking=false;verification=null;verificationFailure=null;running=start;paused=false;hasStarted=start;accumulator=0;lastEvents=-1;
 exp=createChallenge(config,weights);$('share-box').hidden=true;$('pause').textContent='Pause';$('run').textContent=start?'Run again ↻':'Run challenge →';$('verification-status').textContent='Run a challenge first';message('');render();
}
function updateConfig(next){try{config=validateConfig(next);syncControls();newTrial(false);if(!initializing&&location.hash)history.replaceState(null,'',location.pathname);}catch(error){message(error.message);syncControls();}}
function context(canvas){const rect=canvas.getBoundingClientRect(),scale=Math.min(devicePixelRatio||1,2),width=Math.max(1,Math.round(rect.width*scale)),height=Math.max(1,Math.round(rect.height*scale));if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}const ctx=canvas.getContext('2d');ctx.setTransform(scale,0,0,scale,0,0);return {ctx,w:rect.width,h:rect.height};}
function draw(canvas,arm,color){const {ctx,w,h}=context(canvas);ctx.fillStyle='#0f1c24';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#1b303b';ctx.lineWidth=1;for(let i=1;i<12;i++){ctx.beginPath();ctx.moveTo(w*i/12,0);ctx.lineTo(w*i/12,h);ctx.stroke();ctx.beginPath();ctx.moveTo(0,h*i/12);ctx.lineTo(w,h*i/12);ctx.stroke();}ctx.strokeStyle='#294550';ctx.strokeRect(.045*w,.055*h,.91*w,.89*h);
 const target=arm.state.target,tx=target.x*w,ty=target.y*h,rx=config.radius*w,ry=config.radius*h;ctx.beginPath();ctx.ellipse(tx,ty,rx,ry,0,0,Math.PI*2);ctx.strokeStyle=arm.hidden?'#607985':'#e1c574';ctx.setLineDash(arm.hidden?[4,5]:[]);ctx.lineWidth=1.6;ctx.stroke();ctx.setLineDash([]);if(!arm.hidden){ctx.fillStyle='#e1c57418';ctx.fill();ctx.beginPath();ctx.arc(tx,ty,Math.max(2.5,w*.006),0,Math.PI*2);ctx.fillStyle='#e1c574';ctx.fill();}else{ctx.fillStyle='#8299a4';ctx.font=`${Math.max(8,Math.min(10,w*.03))}px "IBM Plex Mono",monospace`;ctx.textAlign='center';ctx.fillText('HIDDEN',tx,Math.max(15,ty-ry-9));}
 if(!hasStarted){ctx.font=`${Math.max(10,Math.min(13,w*.035))}px "Source Sans 3",sans-serif`;ctx.textAlign='center';ctx.fillStyle='#a1b7c1';ctx.fillText('Click to place the target',w/2,h*.52);}
 const path=arm.path;ctx.beginPath();for(let i=0;i<path.length;i++){if(i===0)ctx.moveTo(path[i].x*w,path[i].y*h);else ctx.lineTo(path[i].x*w,path[i].y*h);}ctx.strokeStyle=color+'bb';ctx.lineWidth=1.7;ctx.stroke();const fish=arm.state.fish,s=Math.max(5,w*.017);ctx.save();ctx.translate(fish.x*w,fish.y*h);ctx.rotate(fish.heading);ctx.beginPath();ctx.moveTo(s*1.4,0);ctx.lineTo(-s*.8,-s*.65);ctx.lineTo(-s*.4,0);ctx.lineTo(-s*.8,s*.65);ctx.closePath();ctx.fillStyle=color;ctx.fill();ctx.restore();if(arm.reached){ctx.beginPath();ctx.arc(fish.x*w,fish.y*h,Math.max(8,w*.025),0,Math.PI*2);ctx.strokeStyle=color;ctx.stroke();}ctx.font=`${Math.max(8,Math.min(10,w*.025))}px "IBM Plex Mono",monospace`;ctx.fillStyle='#78929e';ctx.textAlign='left';ctx.fillText(arm.hidden?'NO VISUAL INPUT':'VISUAL INPUT ON',w*.065,h*.975);
}
function renderEvents(){if(exp.events.length===lastEvents)return;lastEvents=exp.events.length;$('event-log').replaceChildren();for(const event of exp.events.slice().reverse()){const row=document.createElement('li'),time=document.createElement('time'),kind=document.createElement('span'),detail=document.createElement('span');time.textContent=`${n(event.modelTime??event.time??event.t??0)} s`;kind.className='event-kind';kind.textContent=event.kind;detail.className='event-detail';detail.textContent=event.text||event.detail||event.kind;row.append(time,kind,detail);$('event-log').append(row);}}
function describeResult(){const a=exp.arms.baseline,b=exp.arms.learned;if(!exp.finished){$('outcome-title').textContent=hasStarted?(paused?'The challenge is paused.':'The challenge is running.'):'What will the model do?';$('outcome').textContent=hasStarted?(b.reached?`The saved controller reached the target at ${n(b.result.timeToTarget)} s. The original controller is still running.`:a.reached?`The original controller reached the target at ${n(a.result.timeToTarget)} s. The saved controller is still running.`:'Both controllers receive the same task. Their trajectories come from the model, and either controller may finish first.'):'Choose a task and press Run challenge. Results are measured from the actual controller trajectories.';return;}
 if(a.reached&&b.reached){const difference=a.result.timeToTarget-b.result.timeToTarget;$('outcome-title').textContent=Math.abs(difference)<.011?'Both arrived together.':difference>0?'The saved controller arrived first.':'The original controller arrived first.';$('outcome').textContent=`Original: ${n(a.result.timeToTarget)} s. Saved: ${n(b.result.timeToTarget)} s. ${Math.abs(difference)<.011?'The recorded arrival times are equal.':`${n(Math.abs(difference))} s separates these two attempts.`}`;}
 else if(a.reached||b.reached){const winner=b.reached?'saved':'original',time=b.reached?b.result.timeToTarget:a.result.timeToTarget;$('outcome-title').textContent=`Only the ${winner} controller reached the target.`;$('outcome').textContent=`It arrived at ${n(time)} s. The other controller did not reach the target within ${config.duration} model seconds.`;}
 else{$('outcome-title').textContent='Neither controller reached the target.';$('outcome').textContent=`Both reached the ${config.duration}-second limit. Closest distance: original ${n(a.result.closestDistance,3)}, saved ${n(b.result.closestDistance,3)} arena units.`;}
}
function render(){if(!exp)return;$('challenge-status').textContent=exp.finished?'Challenge complete':!hasStarted?'Ready to run':paused?'Paused':'Running';$('model-time').textContent=`${n(exp.time)} / ${n(config.duration)} s`;$('target-position').textContent=`${n(exp.target?.x??config.target.x)}, ${n(exp.target?.y??config.target.y)}`;$('pause').disabled=!hasStarted||exp.finished;$('run-label').textContent=exp.finished?'COMPLETED TRIAL':hasStarted?'CURRENT TRIAL':'NO RESULT YET';
 $('verification-status').textContent=checking?'Recomputing on server':verificationFailure?'Check failed':verification?'Matches server result':exp.finished?'Not yet checked':hasStarted?'Waiting for completion':'Run a challenge first';$('verify').disabled=!exp.finished||checking;$('export').disabled=!hasStarted;$('share').disabled=!ready;
 $('verification-detail').textContent=verification?`Recomputed with the same task and exact gains at ${new Date(verification.verifiedAt).toLocaleTimeString('en-GB')}. Both results match. This check confirms reproducibility, not the source of shared parameters.`:verificationFailure||'After a completed trial, the server independently repeats the task with the same parameters.';
 for(const [name,color] of [['baseline','#93a8b5'],['learned','#86cfb6']]){const arm=exp.arms[name];draw($(`${name}-arena`),arm,color);$(`${name}-signal`).textContent=arm.hidden?'Visual input off':'Visual input on';$(`${name}-result`).textContent=arm.reached?`Reached · ${n(arm.result.timeToTarget)} s`:arm.finished?'Time limit reached':!hasStarted?'Ready':`${paused?'Paused':'Running'} · ${n(arm.state.time)} s`;$(`${name}-path`).textContent=`Path ${n(arm.pathLength,3)}`;}
 const state=exp.arms.learned.state;brain.setRates(state.rates);rateRows.forEach(({value,bar},i)=>{value.textContent=n(state.rates[i],3);bar.style.width=`${state.rates[i]*100}%`;});const ctx=$('retina').getContext('2d');for(let y=0;y<16;y++)for(let x=0;x<32;x++){const c=Math.round(state.retina[y*32+x]*255);ctx.fillStyle=`rgb(${c},${c},${c})`;ctx.fillRect(x*10,y*10,10,10);}
 const motions={still:'Stationary target',sweep:'Target moves side to side',switch:'Target switches sides at 4 s'};$('task-description').textContent=`${motions[config.motion]}${config.occlusion.enabled?` · hidden ${config.occlusion.at}–${config.occlusion.at+config.occlusion.duration} s`:''}`;renderEvents();describeResult();}
function compareResults(server){for(const name of ['baseline','learned']){const a=exp.arms[name].result,b=server.results?.[name];if(!b||a.reached!==b.reached)throw Error('The server outcome differs from the browser outcome.');for(const key of ['duration','timeToTarget','pathLength','closestDistance','finalDistance']){if(a[key]===null&&b[key]===null)continue;if(!Number.isFinite(a[key])||!Number.isFinite(b[key])||Math.abs(a[key]-b[key])>1e-8)throw Error(`The server ${key} differs for the ${name} controller.`);}}}
async function verifyResult(){if(!exp?.finished||checking)return;const currentRun=runId;checking=true;verificationFailure=null;const controller=new AbortController();checkAbort=controller;const timeout=setTimeout(()=>controller.abort(),12000);render();try{const data=await json('/api/challenge-verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({config,weights}),signal:controller.signal});if(runId!==currentRun)return;compareResults(data);verification=data;}catch(error){if(runId===currentRun)verificationFailure=`Result check failed: ${error.message}`;}finally{clearTimeout(timeout);if(runId===currentRun){checking=false;render();}}}
function animate(now){const elapsed=Math.min(.1,(now-lastFrame)/1000);lastFrame=now;if(exp&&running&&!paused&&!exp.finished&&!document.hidden){accumulator+=elapsed*Number($('playback').value);while(accumulator>=DT){stepChallenge(exp);accumulator-=DT;if(exp.finished){running=false;void verifyResult();break;}}}else accumulator=0;if(exp&&now-lastPaint>=65){render();lastPaint=now;}requestAnimationFrame(animate);}
$('run').addEventListener('click',()=>newTrial(true));$('pause').addEventListener('click',()=>{paused=!paused;$('pause').textContent=paused?'Resume':'Pause';render();});$('reset').addEventListener('click',()=>updateConfig(copy(DEFAULT_CONFIG)));
$('preset').addEventListener('change',()=>{const preset=presetEntries.find(p=>p.id===$('preset').value);if(preset)updateConfig(copy(preset.config));});
for(const id of ['motion','motion-speed','contrast','radius','occlusion','hide-at','hide-for'])$(id).addEventListener(id==='motion'||id==='occlusion'?'change':'input',()=>{const next=copy(config);next.motion=$('motion').value;next.speed=Number($('motion-speed').value);next.contrast=Number($('contrast').value);next.radius=Number($('radius').value);next.occlusion={enabled:$('occlusion').checked,at:Number($('hide-at').value),duration:Number($('hide-for').value)};updateConfig(next);});
for(const id of ['baseline-arena','learned-arena'])$(id).addEventListener('click',event=>{if(!ready)return;const rect=event.currentTarget.getBoundingClientRect();updateConfig({...copy(config),target:{x:+Math.max(.1,Math.min(.9,(event.clientX-rect.left)/rect.width)).toFixed(3),y:+Math.max(.1,Math.min(.85,(event.clientY-rect.top)/rect.height)).toFixed(3)}});});
$('share').addEventListener('click',async()=>{try{const encoded=encodeChallenge({config,weights,provenance}),url=`${location.origin}${location.pathname}#challenge=${encoded}`;$('share-url').value=url;$('share-box').hidden=false;try{await navigator.clipboard.writeText(url);$('share-status').textContent='Copied. The link preserves the task and exact parameters so others can repeat it.';}catch{$('share-url').focus();$('share-url').select();$('share-status').textContent='Copy this selected link to repeat the same task with the same parameters.';}}catch(error){message(error.message);}});
$('export').addEventListener('click',()=>{const payload={...exportChallenge(exp),exportedAt:new Date().toISOString(),provenance,verification,verificationFailure};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download=`challenge-the-fish-${Date.now()}.json`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('verify').addEventListener('click',()=>void verifyResult());
document.addEventListener('visibilitychange',()=>{accumulator=0;lastFrame=performance.now();});
async function init(){try{let shared=null;if(location.hash.startsWith('#challenge=')){try{shared=decodeChallenge(location.hash.slice(11));}catch(error){throw Error(`This challenge link is invalid: ${error.message}`);}}
 if(shared){config=shared.config;weights=shared.weights;provenance=shared.provenance||{};generationLabel=Number.isInteger(provenance.championGeneration)?`Shared generation ${provenance.championGeneration}`:'Shared controller';$('source-date').textContent='Parameters supplied by the link';$('source-notice').textContent='This link restores the exact task and parameters. Shared metadata is supplied with the link; result checks do not certify its origin.';}
 else{const data=await json('/api/challenge-weights');weights=data.weights;generationLabel=data.source==='public-learning'?`Saved generation ${data.championGeneration}`:'Original parameter fallback';provenance={championGeneration:data.championGeneration,capturedAt:data.sourceAt||data.fetchedAt,label:data.source==='public-learning'?'Public saved controller':'Original fixed parameters'};if(data.sourceUrl)provenance.source=data.sourceUrl;$('source-date').textContent=data.source==='public-learning'?new Date(data.sourceAt).toLocaleString('en-GB'):'Public parameters unavailable';$('source-notice').textContent=data.source==='public-learning'?`Using a frozen copy of saved generation ${data.championGeneration}. This challenge runs in your browser and never changes the shared learner.`:data.notice;}
 $('parameter-label').textContent=generationLabel;if(generationLabel==='Original parameter fallback')$('learned-heading').textContent='Fallback controller';ready=true;document.querySelectorAll('.designer button,.designer select,.designer input').forEach(element=>element.disabled=false);$('share').disabled=false;syncControls();newTrial(false);initializing=false;
 }catch(error){$('challenge-status').textContent='Could not load';$('source-notice').textContent=error.message;message('Reload without the challenge fragment to start a fresh task.');}}
requestAnimationFrame(animate);void init();
